'use client';

import { useState } from 'react';
import Link from 'next/link';
import Header from '@/components/Header';
import Footer from '@/components/Footer';
import Modal from '@/components/Modal';

export default function Home() {
  const [modalOpen, setModalOpen] = useState(false);
  const [modalData, setModalData] = useState({ title: '', description: '' });

  const abrirModal = (title: string, description: string) => {
    setModalData({ title, description });
    setModalOpen(true);
  };

  // VEJA AQUI: Coloque os links das imagens direto na propriedade 'img'
  const novidades = [
    { 
      id: 1, 
      title: 'Lies of P Overture', 
      img: 'https://i.ytimg.com/vi/TkCOWLrh26s/hq720.jpg?sqp=-oaymwEhCK4FEIIDSFryq4qpAxMIARUAAAAAGAElAADIQj0AgKJD&rs=AOn4CLDAQkKem7LEP_ZJOTl4LZZjjb4z8Q', 
      desc: 'Uma nova e sombria expansão no mundo de Krat, expandindo os mistérios de Pinóquio.' 
    },
    { 
      id: 2, 
      title: 'Hollow Knight', 
      img: 'https://cdn.awsli.com.br/800x800/229/229111/produto/346762626/1-tgg1vtswva.png', 
      desc: 'Explore um reino vasto e arruinado de insetos e heróis em um clássico estilo metroidvania.' 
    },
    { 
      id: 3, 
      title: "No, I'm not a human", 
      img: 'https://m.media-amazon.com/images/M/MV5BNjQ2YjhkNDQtMTIxOS00ZDgxLWFiNGEtOTFjZmNiODE1YzVjXkEyXkFqcGc@._V1_QL75_UY281_CR21,0,190,281_.jpg', 
      desc: 'Um jogo de terror psicológico tenso onde você deve provar sua própria consciência.' 
    },
    { 
      id: 4, 
      title: 'Astro Bot', 
      img: 'https://image.api.playstation.com/vulcan/ap/rnd/202406/0500/8f15268257b878597757fcc5f2c9545840867bc71fc863b1.png', 
      desc: 'Uma jornada de plataforma espetacular celebrando a história dos videogames.' 
    },
  ];

  const noticias = [
    { 
      id: 1, 
      title: 'Pokémon Ventos e Ondas chega em 2027', 
      sub: 'Com tradução oficial para português brasileiro confirmada pela desenvolvedora.', 
      data: 'HÁ 3 DIAS', 
      img: 'https://www.adrenaline.com.br/wp-content/uploads/2026/02/pokemon-ventos-ondas-oficial.jpg', // Link da imagem da notícia
      text: 'Os fãs brasileiros finalmente receberão suporte completo e localização na nova geração de monstrinhos.' 
    },
    { 
      id: 2, 
      title: 'Resident Evil Requiem destrói recorde', 
      sub: 'O jogo alcançou o maior pico de jogadores simultâneos na Steam para toda a franquia.', 
      data: 'HÁ 5 DIAS', 
      img: 'https://www.adrenaline.com.br/wp-content/uploads/2026/02/resident-evil-requiem-recorde-steam.jpg',
      text: 'Com gráficos de última geração e o retorno de mecânicas clássicas de Survival Horror.' 
    },
  ];

  const maisVendidos = [
    { id: 1, title: 'Minecraft', img: 'data:image/jpeg;base64,', desc: 'Construa qualquer coisa que puder imaginar.' },
    { id: 2, title: 'Red Dead Redemption II', img: 'data:image/jpeg;base64,', desc: 'Uma história épica sobre a vida no coração do Velho Oeste.' },
    { id: 3, title: 'Dark Souls III', img: 'https://store-images.s-microsoft.com/image/apps.24212.71827372323164480.6e97c7d2-899a-404f-8660-d622a7fc9162.daea9ed5-4921-45a6-a188-637bfab7176c', desc: 'Prepare-se para abraçar a escuridão mais uma vez.' },
    { id: 4, title: 'Em breve', img: '', desc: 'Este slot está reservado para os próximos grandes lançamentos.' },
  ];

  return (
    <div className="min-h-screen bg-black flex flex-col justify-between">
      <div>
        <Header />

        <main className="max-w-7xl mx-auto px-6 py-8 flex flex-col gap-12">
          
          {/* BARRA DE PESQUISA E LINKS */}
          <div className="flex items-center gap-8 bg-black py-4 sticky top-0 z-40">
            <div className="relative">
              <input 
                type="text" 
                placeholder="Pesquisar loja" 
                className="bg-zinc-800 text-sm text-zinc-300 pl-10 pr-4 py-2 rounded-full w-64 focus:outline-none focus:ring-1 focus:ring-zinc-500"
              />

            </div>

            <nav className="flex gap-6 text-sm font-bold tracking-wide">
              <Link href="#" className="hover:text-zinc-400 transition">NOVIDADES</Link>
              <Link href="#" className="hover:text-zinc-400 transition">PRODUTOS</Link>
            </nav>
          </div>

          {/* SEÇÃO 1: NOVIDADES DA SEMANA */}
          <section>
            <h2 className="text-xl font-bold uppercase tracking-wider mb-6">Novidades da Semana</h2>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
              {novidades.map((jogo) => (
                <div 
                  key={jogo.id} 
                  onClick={() => abrirModal(jogo.title, jogo.desc)}
                  className="group cursor-pointer flex flex-col gap-3"
                >
                  {/* ARRUMADO: O link entra apenas no src do img abaixo */}
                  <div className="aspect-[3/4] bg-zinc-900 border border-zinc-800 rounded-lg overflow-hidden group-hover:border-zinc-500 transition duration-300">
                    <img 
                      src={jogo.img} 
                      alt={jogo.title}
                      className="w-full h-full object-cover" 
                    />
                  </div>
                  <h3 className="text-sm font-medium text-zinc-400 group-hover:text-white transition">
                    {jogo.title}
                  </h3>
                </div>
              ))}
            </div>
          </section>

          {/* SEÇÃO 2: NOTÍCIAS DO MÊS */}
          <section>
            <h2 className="text-xl font-bold uppercase tracking-wider mb-6">Notícias do Mês</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              {noticias.map((noti) => (
                <div 
                  key={noti.id}
                  onClick={() => abrirModal(noti.title, noti.text)}
                  className="group cursor-pointer flex flex-col gap-4"
                >
                  {/* ARRUMADO: Imagem de notícia sem vazar link */}
                  <div className="aspect-video bg-zinc-900 border border-zinc-800 rounded-xl overflow-hidden group-hover:border-zinc-500 transition duration-300">
                    <img 
                      src={noti.img} 
                      alt={noti.title}
                      className="w-full h-full object-cover"
                    />
                  </div>
                  <div className="flex flex-col gap-1">
                    <span className="text-xs text-zinc-500 font-bold">{noti.data}</span>
                    <h3 className="text-lg font-bold text-white group-hover:text-blue-400 transition">
                      {noti.title}
                    </h3>
                    <p className="text-sm text-zinc-400 line-clamp-2">{noti.sub}</p>
                  </div>
                </div>
              ))}
            </div>
          </section>

          {/* SEÇÃO 3: MAIS VENDIDOS */}
          <section>
            <h2 className="text-xl font-bold uppercase tracking-wider mb-6">Mais Vendidos</h2>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
              {maisVendidos.map((jogo) => (
                <div 
                  key={jogo.id} 
                  onClick={() => abrirModal(jogo.title, jogo.desc)}
                  className="group cursor-pointer flex flex-col gap-3"
                >
                  {/* ARRUMADO: Imagem dos mais vendidos corrigida */}
                  <div className="aspect-[3/4] bg-zinc-900 border border-zinc-800 rounded-lg overflow-hidden group-hover:border-zinc-500 transition duration-300">
                    <img 
                      src={jogo.img} 
                      alt={jogo.title}
                      className="w-full h-full object-cover" 
                    />
                  </div>
                  <h3 className="text-sm font-medium text-zinc-400 group-hover:text-white transition">
                    {jogo.title}
                  </h3>
                </div>
              ))}
            </div>
          </section>

        </main>
      </div>

      <Footer />

      <Modal 
        isOpen={modalOpen} 
        onClose={() => setModalOpen(false)} 
        title={modalData.title} 
        description={modalData.description} 
      />
    </div>
  );
}